using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient();

builder.Services.AddChatClient(chatClientBuilder => chatClientBuilder
    .UseLogging()
    .Use(innerClient => new OpenAIClientExtensions.OpenAIChatClientWrapper(
        builder.Configuration["AI:ApiKey"]
            ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set the API key via AI:ApiKey in config or OPENAI_API_KEY env var."),
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18")));

builder.Services.AddSingleton<NoteService>();
builder.Services.AddSingleton<ResearchTools>();

builder.Logging.SetMinimumLevel(LogLevel.Warning);

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.ReadUrl),
    AIFunctionFactory.Create(noteService.SaveNote),
    AIFunctionFactory.Create(noteService.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the SearchWeb tool.
        2. Read promising URLs with the ReadUrl tool to get details.
        3. Save key findings as notes using the SaveNote tool.
        4. After gathering enough information, use GetNotes to review all notes.
        5. Provide a comprehensive summary with key points and sources.

        Be thorough but focused. Save 3-5 notes covering different aspects of the topic.
        Always cite your sources in the final summary.
        """,
