var session = await agent.CreateSessionAsync("research-session");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    noteService.Clear();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching...\n");
    Console.ResetColor();

    try
    {
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
        });

        var response = await agent.RunAsync(
            $"Research the following topic and provide a detailed summary: {input}",
            session,
            options: runOptions);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══ Research Summary ═══\n");
        Console.ResetColor();
        Console.WriteLine(response.Text);

        if (response.Usage is { } usage)
        {
            Console.ForegroundColor = ConsoleColor.DarkGray;
            Console.WriteLine($"\n[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}]");
            Console.ResetColor();
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

