using System.ComponentModel;
using System.Text.Json;
using System.Web;

namespace ResearchAgent;

/// <summary>
/// Provides web search and URL reading tools for the research agent.
/// </summary>
public sealed class ResearchTools(IHttpClientFactory httpClientFactory)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [Description("Search the web for information on a given query. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
    {
        using var client = httpClientFactory.CreateClient();
        client.DefaultRequestHeaders.Add("User-Agent", "ResearchAgent/1.0");
        client.Timeout = TimeSpan.FromSeconds(15);

        // Use DuckDuckGo's HTML endpoint for a no-API-key search experience.
        var encoded = HttpUtility.UrlEncode(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
        var html = await client.GetStringAsync(url);

        var results = ParseDuckDuckGoResults(html, maxResults);

        if (results.Count == 0)
            return "No results found for the query.";

        return JsonSerializer.Serialize(results, JsonOptions);
    }

    [Description("Read and extract text content from a URL. Returns the page content as plain text (truncated to ~3000 characters).")]
    public async Task<string> ReadUrl(
        [Description("The URL to read")] string url)
    {
        using var client = httpClientFactory.CreateClient();
        client.DefaultRequestHeaders.Add("User-Agent", "ResearchAgent/1.0");
        client.Timeout = TimeSpan.FromSeconds(15);

        try
        {
            var html = await client.GetStringAsync(url);
            var text = StripHtmlTags(html);

            const int maxLength = 3000;
            if (text.Length > maxLength)
                text = text[..maxLength] + "\n\n[Content truncated...]";

            return text;
        }
        catch (Exception ex)
        {
            return $"Failed to read URL: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseDuckDuckGoResults(string html, int maxResults)
    {
        var results = new List<SearchResult>();

        // Parse result blocks from DuckDuckGo HTML response.
        var searchIndex = 0;
        while (results.Count < maxResults)
        {
            var linkStart = html.IndexOf("class=\"result__a\"", searchIndex, StringComparison.Ordinal);
            if (linkStart < 0) break;

            var hrefStart = html.LastIndexOf("href=\"", linkStart, Math.Min(linkStart, 200), StringComparison.Ordinal);
            if (hrefStart < 0) { searchIndex = linkStart + 1; continue; }

            hrefStart += 6;
            var hrefEnd = html.IndexOf('"', hrefStart);
            if (hrefEnd < 0) { searchIndex = linkStart + 1; continue; }

            var rawUrl = html[hrefStart..hrefEnd];

            // DuckDuckGo wraps URLs in a redirect; extract the actual target.
            if (rawUrl.Contains("uddg=", StringComparison.Ordinal))
            {
                var uddgStart = rawUrl.IndexOf("uddg=", StringComparison.Ordinal) + 5;
                var uddgEnd = rawUrl.IndexOf('&', uddgStart);
                rawUrl = HttpUtility.UrlDecode(uddgEnd > 0 ? rawUrl[uddgStart..uddgEnd] : rawUrl[uddgStart..]);
            }

            // Extract the link text as the title.
            var tagClose = html.IndexOf('>', linkStart);
            var tagEnd = html.IndexOf("</a>", tagClose, StringComparison.Ordinal);
            var title = tagClose >= 0 && tagEnd > tagClose
                ? StripHtmlTags(html[(tagClose + 1)..tagEnd]).Trim()
                : "(no title)";

            // Extract the snippet.
            var snippetStart = html.IndexOf("class=\"result__snippet\"", linkStart, StringComparison.Ordinal);
            var snippet = string.Empty;
            if (snippetStart >= 0)
            {
                var sTagClose = html.IndexOf('>', snippetStart);
                var sTagEnd = html.IndexOf("</a>", sTagClose, StringComparison.Ordinal);
                if (sTagClose >= 0 && sTagEnd > sTagClose)
                    snippet = StripHtmlTags(html[(sTagClose + 1)..sTagEnd]).Trim();
            }

            results.Add(new SearchResult(title, rawUrl, snippet));
            searchIndex = linkStart + 1;
        }

        return results;
    }

    private static string StripHtmlTags(string html)
    {
        // Remove script and style blocks, then strip remaining tags.
        var text = System.Text.RegularExpressions.Regex.Replace(
            html, @"<(script|style)[^>]*>.*?</\1>", "", System.Text.RegularExpressions.RegexOptions.Singleline);
        text = System.Text.RegularExpressions.Regex.Replace(text, @"<[^>]+>", " ");
        text = HttpUtility.HtmlDecode(text);
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
        return text.Trim();
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking tools for the research agent to store and retrieve findings.
/// </summary>
public sealed class NoteService
{
    private readonly List<Note> _notes = [];
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [Description("Save a research note with a title and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content/findings to save")] string content,
        [Description("The source URL where this information was found")] string sourceUrl)
    {
        var note = new Note(title, content, sourceUrl, DateTimeOffset.UtcNow);
        _notes.Add(note);
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieve all saved research notes. Use this to review findings before writing the final summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return JsonSerializer.Serialize(_notes, JsonOptions);
    }

    public void Clear() => _notes.Clear();

    private sealed record Note(string Title, string Content, string SourceUrl, DateTimeOffset SavedAt);
}

